func (l *base) detectScanDest() map[string][]string {
	scanDest := map[string][]string{}

	for _, p := range l.osPackages.Packages {
		if p.AffectedProcs == nil {
			continue
		}
		for _, proc := range p.AffectedProcs {
			if proc.ListenPorts == nil {
				continue
			}
			for _, port := range proc.ListenPorts {
				addrs := []string{port.Address}
				if port.Address == "*" {
					addrs = l.ServerInfo.IPv4Addrs
				}
				for _, addr := range addrs {
					scanDest[addr] = append(scanDest[addr], port.Port)
				}
			}
		}
	}

	for addr, ports := range scanDest {
		sort.Strings(ports)
		unique := ports[:0]
		for _, port := range ports {
			if len(unique) == 0 || unique[len(unique)-1] != port {
				unique = append(unique, port)
			}
		}
		scanDest[addr] = unique
	}

	return scanDest
}

func (l *base) execPortsScan(scanDest map[string][]string) ([]string, error) {
	listenIPPorts := []string{}

	addrs := make([]string, 0, len(scanDest))
	for addr := range scanDest {
		addrs = append(addrs, addr)
	}
	sort.Strings(addrs)
	for _, addr := range addrs {
		for _, port := range scanDest[addr] {
			ipPort := addr + ":" + port
			conn, err := net.DialTimeout("tcp", ipPort, time.Duration(1)*time.Second)
			if err != nil {
				continue
			}
			conn.Close()
			listenIPPorts = append(listenIPPorts, ipPort)
		}
	}

	return listenIPPorts, nil
}

func (l *base) updatePortStatus(listenIPPorts []string) {
	for name, p := range l.osPackages.Packages {
		if p.AffectedProcs == nil {
			continue
		}
		for i, proc := range p.AffectedProcs {
			if proc.ListenPorts == nil {
				continue
			}
			for j, port := range proc.ListenPorts {
				l.osPackages.Packages[name].AffectedProcs[i].ListenPorts[j].PortScanSuccessOn = l.findPortScanSuccessOn(listenIPPorts, port)
			}
